# Shift `<file>.gd:N` (and a bare `:N` after it on the same line) in the system pages to the new line numbers.
# Usage: remap.py <base tree> <work tree> <rel path>...
import difflib, re, sys, glob, os
base, work, rels = sys.argv[1], sys.argv[2], sys.argv[3:]
maps = {}
for rel in rels:
    a = open(os.path.join(base, rel)).read().split('\n'); b = open(os.path.join(work, rel)).read().split('\n')
    m = {}
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        for k in range(i1, i2):
            m[k + 1] = (j1 + (k - i1) + 1) if tag == 'equal' else None
    maps[os.path.basename(rel)] = m
pat = re.compile(r'([\w/]*?(' + '|'.join(re.escape(k) for k in maps) + r'|[\w]+\.gd)):(\d+)|`:(\d+)`')
changed = []
for page in sorted(glob.glob(os.path.join(work, 'docs/kod_haritasi/sistemler/*.md'))):
    lines = open(page).read().split('\n'); out = []
    for ln, line in enumerate(lines, 1):
        last = None
        def sub(mo):
            global last
            if mo.group(1):
                last = os.path.basename(mo.group(1))
                if last in maps:
                    n = int(mo.group(3)); new = maps[last].get(n)
                    if new is None:
                        changed.append('UNMAPPED %s:%d %s:%d' % (os.path.basename(page), ln, last, n)); return mo.group(0)
                    if new != n: changed.append('%s:%d %s:%d -> %d' % (os.path.basename(page), ln, last, n, new))
                    return '%s:%d' % (mo.group(1), new)
                return mo.group(0)
            if last in maps:
                n = int(mo.group(4)); new = maps[last].get(n)
                if new is None:
                    changed.append('UNMAPPED %s:%d bare %s:%d' % (os.path.basename(page), ln, last, n)); return mo.group(0)
                if new != n: changed.append('%s:%d bare %s:%d -> %d' % (os.path.basename(page), ln, last, n, new))
                return '`:%d`' % new
            return mo.group(0)
        out.append(pat.sub(sub, line))
    new_text = '\n'.join(out)
    if new_text != '\n'.join(lines):
        open(page, 'w').write(new_text)
print('\n'.join(changed))
EOF
