	if OS.is_debug_build():
		# Both themes are generated from UiTokens by hand; a forgotten regen is caught only here.
		# An unstamped .tres reads 0 and warns too.
		for th: Theme in [ThemeDB.get_project_theme(), load(UiTokens.MENAJER_THEME)]:
			var baked_stamp: int = th.get_constant(&"stamp", &"UiTokensStamp")
			if baked_stamp != UiTokens.THEME_STAMP:
				push_warning("[Theme] %s BAYAT: gömülü damga %d != UiTokens.THEME_STAMP %d — regen: godot --headless --path . -s res://scripts/theme/build_theme.gd" % [th.resource_path.get_file(), baked_stamp, UiTokens.THEME_STAMP])
		# Shift+F4 (game_shell.gd) re-triggers onboarding from a running game.
		EventBus.debug_onboarding_retrigger_requested.connect(_on_debug_onboarding_retrigger)
		if _run_debug_harness():
			return
		# The editor F5's --skip-onboarding goes straight to the shell; --menu on the command line keeps the menu.
		if "--skip-onboarding" in _run_args() and not "--menu" in OS.get_cmdline_args():
			_skip_to_shell()
			return
	_mount_godot_card()


## Once per process, between the boot splash and the menu.
func _mount_godot_card() -> void:
	_state = "card"
	var card: Control = GODOT_CARD.instantiate()
	var shown: int = Time.get_ticks_msec()
	card.finished.connect(func() -> void:
		print("BOOT|card_ms=%d" % (Time.get_ticks_msec() - shown))
		card.queue_free()
		_mount_menu())
	add_child(card)


## The menu is where no run is: the save gate reads "no run", nothing is unsaved and the clock stops.
func _mount_menu() -> void:
	_state = "menu"
	SaveManager.end_run()
	_menu = MAIN_MENU.instantiate()

